parameters.jsCode:
// Apify run-sync-get-dataset-items returns an ARRAY of items.
// Each Apify Crunchbase actor has a different schema; this code handles the common shape:
// { name, full_name, person_name, organization, primary_organization, primary_organization_name,
//   website, domain, categories, last_investment_date, ... }
// Adjust field names below if your actor returns different keys.

const items = Array.isArray($input.first().json) ? $input.first().json : ($input.first().json.items || []);

function pickName(it) {
  return it.full_name || it.person_name || it.name || `${it.first_name || ''} ${it.last_name || ''}`.trim() || null;
}
function pickCompany(it) {
  return it.primary_organization_name || it.primary_organization || it.organization || it.company || null;
}
function pickDomain(it) {
  const url = it.website || it.domain || it.organization_website || it.primary_organization_website || '';
  if (!url) return null;
  try { return new URL(url.startsWith('http') ? url : `https://${url}`).hostname.replace(/^www\./, ''); }
  catch { return url.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0]; }
}
function splitName(full) {
  if (!full) return { first: '', last: '' };
  const parts = full.trim().split(/\s+/);
  return { first: parts[0] || '', last: parts.slice(1).join(' ') || '' };
}

return items.map(it => {
  const full = pickName(it);
  const { first, last } = splitName(full);
  return {
    json: {
      source: 'Crunchbase',
      full_name: full,
      first_name: first,
      last_name: last,
      company: pickCompany(it),
      domain: pickDomain(it),
      categories: it.categories || it.investor_categories || [],
      raw: it
    }
  };
}).filter(r => r.json.full_name && r.json.domain);

// Lead qualification filter applied BEFORE the dedup/enrich loop.
// Every rejection is console.logged to the n8n execution log with the
// lead name and exact reason. Rules are short-circuited in order so
// each dropped lead shows the FIRST disqualifying reason, not all.

const DISALLOWED_ORGS = ['Anthropic', 'OpenAI', 'Apple', 'Google', 'Amazon'];
const OPERATOR_TITLES = ['CEO', 'CTO', 'Founder', 'Co-Founder', 'Co Founder'];
const MIN_INVESTMENTS = 3;
const MAX_AGE_MONTHS = 12;

const cutoffDate = new Date();
cutoffDate.setMonth(cutoffDate.getMonth() - MAX_AGE_MONTHS);

const kept = [];
const stats = { dropped_investments: 0, dropped_inactive: 0, dropped_operator: 0, dropped_conflict: 0 };

for (const item of $input.all()) {
  const lead = item.json || {};
  const raw = lead.raw || {};
  const name = lead.full_name || 'unknown';
  const fundName = String(lead.company || '').trim().toLowerCase();

  const totalFundingCount = Number(raw.total_funding_count ?? raw.num_investments ?? raw.num_exits ?? 0);
  const lastFundingDateRaw = raw.last_funding_date || raw.last_investment_date || raw.last_funding_on || null;
  const primaryJobTitle = String(raw.primary_job_title || raw.title || '');
  const primaryOrg = String(raw.primary_organization_name || raw.primary_organization || raw.organization || '');

  // Rule 1: fewer than 3 total investments
  if (totalFundingCount < MIN_INVESTMENTS) {
    console.log(`[P2.1 qualify] DROPPED ${name}: fewer than 3 total investments (count=${totalFundingCount})`);
    stats.dropped_investments++;
    continue;
  }

  // Rule 2: last investment older than 12 months
  if (!lastFundingDateRaw) {
    console.log(`[P2.1 qualify] DROPPED ${name}: inactive investor (no last_funding_date on record)`);
    stats.dropped_inactive++;
    continue;
  }
  const lastFundingDate = new Date(lastFundingDateRaw);
  if (isNaN(lastFundingDate.getTime()) || lastFundingDate < cutoffDate) {
    console.log(`[P2.1 qualify] DROPPED ${name}: inactive investor (last_funding_date=${lastFundingDateRaw})`);
    stats.dropped_inactive++;
    continue;
  }

  // Rule 3: full-time operator (has an operator title at an org that is not their own fund)
  const titleLower = primaryJobTitle.toLowerCase();
  const orgLower = primaryOrg.trim().toLowerCase();
  const isOperatorTitle = OPERATOR_TITLES.some(t => titleLower.includes(t.toLowerCase()));
  if (isOperatorTitle && orgLower && orgLower !== fundName) {
    console.log(`[P2.1 qualify] DROPPED ${name}: full-time operator (${primaryJobTitle} at ${primaryOrg})`);
    stats.dropped_operator++;
    continue;
  }

  // Rule 4: conflict of interest (primary org is one of the BigCo AI labs)
  const hasConflict = DISALLOWED_ORGS.some(o => orgLower.includes(o.toLowerCase()));
  if (hasConflict) {
    console.log(`[P2.1 qualify] DROPPED ${name}: conflict of interest (primary_organization=${primaryOrg})`);
    stats.dropped_conflict++;
    continue;
  }

  kept.push(item);
}

console.log(`[P2.1 qualify] kept ${kept.length} | dropped_investments=${stats.dropped_investments} dropped_inactive=${stats.dropped_inactive} dropped_operator=${stats.dropped_operator} dropped_conflict=${stats.dropped_conflict}`);
return kept;

