const items = (($json.data || {}).items_page_by_column_values || {}).items || [];
const threshold = parseInt($env.PHASE_2_QUEUE_PAUSE_THRESHOLD || '30', 10);
return [{ json: { queue_count: items.length, threshold, overflow: items.length > threshold } }];

